"use client"

import * as React from "react"
import type { Selection } from "react-aria-components"

import { Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbList, BreadcrumbPage } from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import { Icon } from "@/components/ui/icon"
import { Item, ItemContent, ItemDescription, ItemGroup, ItemMedia, ItemTitle } from "@/components/ui/item"
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from "@/components/ui/resizable"
import { Tree, TreeItem } from "@/components/ui/tree"

type Node = { id: string; name: string; children?: Node[]; meta?: string }

function findPath(nodes: Node[], id: string, trail: Node[] = []): Node[] | undefined {
  for (const n of nodes) {
    const here = [...trail, n]
    if (n.id === id) return here
    const deeper = n.children && findPath(n.children, id, here)
    if (deeper) return deeper
  }
  return undefined
}

function renderNodes(nodes: Node[]): React.ReactNode {
  return nodes
    .filter((n) => n.children)
    .map((n) => (
      <TreeItem key={n.id} id={n.id} textValue={n.name} icon={<Icon name="folder" />}>
        {renderNodes(n.children ?? [])}
      </TreeItem>
    ))
}

/**
 * Two-pane explorer: folder Tree on the left, the selected folder's entries as
 * a grid list on the right, a breadcrumb trail and a resize handle between.
 */
export default function Explorer({
  heading = "Files",
  nodes = [
    {
      id: "docs",
      name: "Docs",
      children: [
        { id: "guides", name: "Guides", children: [{ id: "start", name: "Getting started.md", meta: "2 KB" }] },
        { id: "readme", name: "Readme.md", meta: "1 KB" },
      ],
    },
    { id: "assets", name: "Assets", children: [{ id: "logo", name: "logo.svg", meta: "4 KB" }] },
  ],
  onOpen,
}: {
  heading?: string
  nodes?: Node[]
  onOpen?: (node: Node) => void
}) {
  const [selected, setSelected] = React.useState<string>(nodes[0]?.id ?? "")
  const path = findPath(nodes, selected) ?? []
  const folder = path.at(-1)
  const entries = folder?.children ?? nodes

  return (
    <section data-slot="explorer" aria-label={heading} className="py-8">
      <div className="mx-auto max-w-5xl px-6">
        <div className="flex items-center justify-between gap-4">
          <Breadcrumb>
            <BreadcrumbList>
              <BreadcrumbItem>
                <BreadcrumbLink onPress={() => setSelected(nodes[0]?.id ?? "")}>{heading}</BreadcrumbLink>
              </BreadcrumbItem>
              {path.map((n, i) => (
                <BreadcrumbItem key={n.id}>
                  {i === path.length - 1 ? <BreadcrumbPage>{n.name}</BreadcrumbPage> : <BreadcrumbLink onPress={() => setSelected(n.id)}>{n.name}</BreadcrumbLink>}
                </BreadcrumbItem>
              ))}
            </BreadcrumbList>
          </Breadcrumb>
          <Button variant="outline" size="sm" isDisabled={path.length < 2} onPress={() => setSelected(path.at(-2)?.id ?? selected)}>
            <Icon name="chevron-up" data-icon="inline-start" />
            Up
          </Button>
        </div>
        <ResizablePanelGroup orientation="horizontal" className="mt-4 min-h-80 rounded-lg border border-border">
          <ResizablePanel defaultSize="30%" minSize="20%">
            <div role="region" aria-label="Folders" className="h-full overflow-auto p-2">
              <Tree
                aria-label="Folders"
                selectionMode="single"
                disallowEmptySelection
                selectedKeys={[selected]}
                defaultExpandedKeys={nodes.map((n) => n.id)}
                onSelectionChange={(keys: Selection) => {
                  if (keys !== "all") {
                    const k = [...keys][0]
                    if (k !== undefined) setSelected(String(k))
                  }
                }}
              >
                {renderNodes(nodes)}
              </Tree>
            </div>
          </ResizablePanel>
          <ResizableHandle withHandle />
          <ResizablePanel defaultSize="70%">
            <div role="region" aria-label="Contents" className="h-full overflow-auto p-2">
              <ItemGroup className="grid gap-1 sm:grid-cols-2">
                {entries.map((n) => (
                  <Item
                    key={n.id}
                    variant="outline"
                    size="sm"
                    role="button"
                    tabIndex={0}
                    onClick={() => (n.children ? setSelected(n.id) : onOpen?.(n))}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") (n.children ? setSelected(n.id) : onOpen?.(n))
                    }}
                    className="cursor-default"
                  >
                    <ItemMedia>
                      <Icon name={n.children ? "folder" : "document"} />
                    </ItemMedia>
                    <ItemContent>
                      <ItemTitle>{n.name}</ItemTitle>
                      <ItemDescription>{n.children ? `${n.children.length} items` : n.meta}</ItemDescription>
                    </ItemContent>
                  </Item>
                ))}
              </ItemGroup>
            </div>
          </ResizablePanel>
        </ResizablePanelGroup>
      </div>
    </section>
  )
}
